oshan.persona.vision.memory.InMemoryGraphStoreimport com.roshan.persona.vision.memory.GraphRAGConnectorimport com.roshan.persona.vision.memory.GraphStoreimport com.roshan.persona.vision.memory.VisualEpisodicMemoryimport com.roshan.persona.vision.ocr.AndroidImageProcessorimport com.roshan.persona.vision.ocr.DocumentFormatDetectorimport com.roshan.persona.vision.ocr.ImageEnhancementPipelineimport com.roshan.persona.vision.ocr.ImageProcessorimport com.roshan.persona.vision.ocr.MlKitOcrRecognizerimport com.roshan.persona.vision.ocr.OcrCacheimport com.roshan.persona.vision.ocr.OcrEngineimport com.roshan.persona.vision.ocr.OcrFieldExtractorimport com.roshan.persona.vision.ocr.OcrRecognizerimport com.roshan.persona.vision.ocr.PrescriptionScannerimport com.roshan.persona.vision.ocr.StructuredDocumentParserimport com.roshan.persona.vision.screen.AccessibilityUiElementDetectorimport com.roshan.persona.vision.screen.AndroidScreenshotCapturerimport com.roshan.persona.vision.screen.LlmScreenSummarizerimport com.roshan.persona.vision.screen.ScreenSummarizerimport com.roshan.persona.vision.screen.ScreenshotCapturerimport com.roshan.persona.vision.screen.ScreenUnderstandingEngineimport com.roshan.persona.vision.screen.UiElementDetectorimport dagger.Moduleimport dagger.Providesimport dagger.hilt.InstallInimport dagger.hilt.android.qualifiers.ApplicationContextimport dagger.hilt.components.SingletonComponentimport kotlinx.coroutines.CoroutineDispatcherimport javax.inject.Singleton/** * NOUS — Vision Hilt Module (Module 6 v4 — Step 6.8, FINAL). * * Wires the [VisionFacade] + all 12+ engines + 4 infrastructure controllers * into the Hilt graph. Binds [OmniSlmEmbedder] + [OmniSlmNerModel] into the * Brain's [EmbedderInterface] + [NerModelInterface] multibinding — **replacing** * Brain's v2 `TfIdfEmbedder` + `null NER`. * * ## What this module provides * *  - All service interfaces as **stub/fake impls** (real Android impls come in *    Module 9 / 10 when NousAccessibilityService + OpenCV + ML Kit ship). *  - All 12+ engines as singletons. *  - 4 infrastructure controllers (Thermal, Battery, Duty Cycling, LMK, Fallback). *  - [VisionFacade] — singleton, aggregates all engines. *  - [OmniSlmEmbedder] + [OmniSlmNerModel] — bound via `@Provides` to Brain's *    [EmbedderInterface] + [NerModelInterface]. * * ## Brain Wiring (the single biggest Brain upgrade) * * Brain's `BuiltInSkillsModule` (in :feature:brain) currently binds: *  - `TfIdfEmbedder` as [EmbedderInterface] (hash-based, semantic-useless) *  - `null` for [NerModelInterface] (regex fallback only) * * This module **OVERRIDES** those bindings: *  - [OmniSlmEmbedder] replaces TfIdfEmbedder → real 384-dim semantic embeddings *  - [OmniSlmNerModel] replaces null NER → real PERSON/ORG/LOCATION + Indian formats * * Expected Brain upgrade: 60% → 95% utterance understanding. * * ## Why stubs? * * The vision engines depend on native libraries (TFLite, ML Kit, OpenCV, * AccessibilityService, FusedLocationProvider). These can't run in unit tests * and aren't yet wired to real Android impls (that's Module 9/10's job). * * For Step 6.8, we provide stubs that return sensible defaults (empty lists, * false, null) so the Hilt graph compiles and the Facade can be injected. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Module 6 → Brain Upgrade Impact</a> */@Module@InstallIn(SingletonComponent::class)object VisionModule {    // ─── Core Infrastructure ─────────────────────────────────────────────    @Provides @Singleton    fun provideModelStore(@ApplicationContext context: Context): ModelStore = ModelStore(context)    @Provides @Singleton    fun provideHardwareProbe(@ApplicationContext context: Context): com.roshan.persona.vision.core.HardwareProbe =        AndroidHardwareProbe(context)    @Provides @Singleton    fun provideDeviceCapabilityDetector(probe: com.roshan.persona.vision.core.HardwareProbe): DeviceCapabilityDetector =        DeviceCapabilityDetector(probe)    @Provides @Singleton    fun provideOmniSlmDelegateFactory(@ApplicationContext context: Context): OmniSlmDelegateFactory = OmniSlmDelegateFactory { _ ->        TfLiteOmniSlmDelegate(context)    }    @Provides @Singleton    fun provideModelManager(        detector: DeviceCapabilityDetector,        store: ModelStore,        factory: OmniSlmDelegateFactory,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): ModelManager = ModelManager(detector, store, factory, dispatcher)    // ─── OmniSlmRuntimeProvider (for Brain bridge) ───────────────────────    @Provides @Singleton    fun provideOmniSlmRuntimeProvider(modelManager: ModelManager): OmniSlmRuntimeProvider =        OmniSlmRuntimeProvider { modelManager.getOmniSlmRuntime() }    // ─── Brain Wiring (REPLACES TfIdfEmbedder + null NER) ────────────────    /**     * Bind [OmniSlmEmbedder] as Brain's [EmbedderInterface].     *     * This OVERRIDES Brain's TfIdfEmbedder binding.     */    @Provides @Singleton    fun provideEmbedderInterface(provider: OmniSlmRuntimeProvider): EmbedderInterface =        OmniSlmEmbedder(provider)    /**     * Bind [OmniSlmNerModel] as Brain's [NerModelInterface].     *     * This replaces Brain's null NER with real entity extraction.     */    @Provides @Singleton    fun provideNerModelInterface(provider: OmniSlmRuntimeProvider): NerModelInterface =        OmniSlmNerModel(provider)    // ─── OCR Engine ──────────────────────────────────────────────────────    @Provides @Singleton    fun provideImageProcessor(): ImageProcessor = AndroidImageProcessor()    @Provides @Singleton    fun provideOcrRecognizer(): OcrRecognizer = MlKitOcrRecognizer()    @Provides @Singleton    fun provideOcrCache(): OcrCache = OcrCache()    @Provides @Singleton    fun provideImageEnhancementPipeline(        processor: ImageProcessor,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): ImageEnhancementPipeline = ImageEnhancementPipeline(processor, dispatcher)    @Provides @Singleton    fun provideOcrFieldExtractor(): OcrFieldExtractor = OcrFieldExtractor()    @Provides @Singleton    fun provideDocumentFormatDetector(): DocumentFormatDetector = DocumentFormatDetector()    @Provides @Singleton    fun providePrescriptionScanner(): PrescriptionScanner = PrescriptionScanner()    @Provides @Singleton    fun provideStructuredDocumentParser(        receiptParser: ReceiptParser,        prescriptionScanner: PrescriptionScanner,        businessCardParser: BusinessCardParser,        governmentIdParser: GovernmentIdParser,        invoiceParser: InvoiceParser,        handwrittenNoteParser: HandwrittenNoteParser,    ): StructuredDocumentParser = StructuredDocumentParser(        receiptParser, prescriptionScanner, businessCardParser,        governmentIdParser, invoiceParser, handwrittenNoteParser,    )    @Provides @Singleton    fun provideOcrEngine(        recognizer: OcrRecognizer,        pipeline: ImageEnhancementPipeline,        extractor: OcrFieldExtractor,        detector: DocumentFormatDetector,        parser: StructuredDocumentParser,        cache: OcrCache,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): OcrEngine = OcrEngine(        recognizer, pipeline, extractor, detector, parser, cache, dispatcher,    )    // ─── Document Scanner ────────────────────────────────────────────────    @Provides @Singleton    fun provideEdgeDetectorDelegate(): EdgeDetectorDelegate = AndroidEdgeDetector()    @Provides @Singleton    fun provideEdgeDetector(delegate: EdgeDetectorDelegate): EdgeDetector = EdgeDetector(delegate)    @Provides @Singleton    fun provideReceiptParser(): ReceiptParser = ReceiptParser()    @Provides @Singleton    fun provideBusinessCardParser(): BusinessCardParser = BusinessCardParser()    @Provides @Singleton    fun provideGovernmentIdParser(): GovernmentIdParser = GovernmentIdParser()    @Provides @Singleton    fun provideInvoiceParser(): InvoiceParser = InvoiceParser()    @Provides @Singleton    fun provideHandwrittenNoteParser(): HandwrittenNoteParser = HandwrittenNoteParser()    @Provides @Singleton    fun provideUnifiedDocumentParser(        receiptParser: ReceiptParser,        prescriptionScanner: PrescriptionScanner,        businessCardParser: BusinessCardParser,        governmentIdParser: GovernmentIdParser,        invoiceParser: InvoiceParser,        handwrittenNoteParser: HandwrittenNoteParser,    ): UnifiedDocumentParser = UnifiedDocumentParser(        receiptParser, prescriptionScanner, businessCardParser,        governmentIdParser, invoiceParser, handwrittenNoteParser,    )    @Provides @Singleton    fun provideDocumentScannerEngine(        edgeDetector: EdgeDetector,        ocrEngine: OcrEngine,        parser: UnifiedDocumentParser,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): DocumentScannerEngine = DocumentScannerEngine(        edgeDetector, ocrEngine, parser, dispatcher,    )    // ─── Object Detection ────────────────────────────────────────────────    @Provides @Singleton    fun provideSsdModelDelegate(): SsdModelDelegate = MlKitObjectDetector()    @Provides @Singleton    fun provideObjectDetector(        delegate: SsdModelDelegate,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): ObjectDetector = ObjectDetector(delegate, dispatcher = dispatcher)    @Provides @Singleton    fun provideRealTimeTracker(): RealTimeTracker = RealTimeTracker()    @Provides @Singleton    fun provideFrameDifferencer(        @IoDispatcher dispatcher: CoroutineDispatcher,    ): FrameDifferencer = AndroidFrameDifferencer(dispatcher)    @Provides @Singleton    fun provideMotionGatingController(differencer: FrameDifferencer): MotionGatingController =        MotionGatingController(differencer)    @Provides @Singleton    fun provideGrayscaleConverter(): GrayscaleConverter = AndroidGrayscaleConverter()    @Provides @Singleton    fun provideObjectDetectionEngine(        detector: ObjectDetector,        tracker: RealTimeTracker,        motionGating: MotionGatingController,        grayscaleConverter: GrayscaleConverter,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): ObjectDetectionEngine = ObjectDetectionEngine(        detector, tracker, motionGating, grayscaleConverter, dispatcher,    )    // ─── Face Detection ──────────────────────────────────────────────────    @Provides @Singleton    fun provideFaceDetectorDelegate(): FaceDetectorDelegate = MlKitFaceDetector()    @Provides @Singleton    fun provideFaceDetectionEngine(        delegate: FaceDetectorDelegate,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): FaceDetectionEngine = FaceDetectionEngine(delegate, dispatcher)    // ─── Barcode + UPI ───────────────────────────────────────────────────    @Provides @Singleton    fun provideBarcodeDetectorDelegate(): BarcodeDetectorDelegate =        MlKitBarcodeScanner()    @Provides @Singleton    fun provideQrPayloadParser(): QrPayloadParser = QrPayloadParser()    @Provides @Singleton    fun provideBarcodeScannerEngine(        delegate: BarcodeDetectorDelegate,        parser: QrPayloadParser,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): BarcodeScannerEngine = BarcodeScannerEngine(delegate, parser, dispatcher)    @Provides @Singleton    fun provideUpiQrHandler(@ApplicationContext context: Context): UpiQrHandler =        UpiQrHandler(context)    // ─── Episodic Memory + Graph RAG ─────────────────────────────────────    @Provides @Singleton    fun provideEpisodicMemoryEncryptor(): EpisodicMemoryEncryptor = AesEpisodicMemoryEncryptor()    @Provides @Singleton    fun provideVisualEpisodicMemory(encryptor: EpisodicMemoryEncryptor): VisualEpisodicMemory =        VisualEpisodicMemory(encryptor = encryptor)    @Provides @Singleton    fun provideGraphStore(): GraphStore = InMemoryGraphStore()    @Provides @Singleton    fun provideGraphRAGConnector(store: GraphStore): GraphRAGConnector = GraphRAGConnector(store)    // ─── Screen Understanding ────────────────────────────────────────────    @Provides @Singleton    fun provideScreenshotCapturer(): ScreenshotCapturer = AndroidScreenshotCapturer()    @Provides @Singleton    fun provideUiElementDetector(): UiElementDetector = AccessibilityUiElementDetector()    @Provides @Singleton    fun provideScreenSummarizer(        llmProvider: com.roshan.persona.brain.llm.provider.LocalLlmProvider,    ): ScreenSummarizer = LlmScreenSummarizer(llmProvider)    @Provides @Singleton    fun provideScreenUnderstandingEngine(        capturer: ScreenshotCapturer,        ocrEngine: OcrEngine,        uiDetector: UiElementDetector,        summarizer: ScreenSummarizer,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): ScreenUnderstandingEngine = ScreenUnderstandingEngine(        capturer, ocrEngine, uiDetector, summarizer, dispatcher,    )    // ─── Infrastructure Controllers ──────────────────────────────────────    @Provides @Singleton    fun provideThermalProbe(@ApplicationContext context: Context): ThermalProbe =        AndroidThermalProbe(context)    @Provides @Singleton    fun provideThermalGovernor(probe: ThermalProbe): ThermalGovernor = ThermalGovernor(probe)    @Provides @Singleton    fun provideAccelerometerProbe(@ApplicationContext context: Context): AccelerometerProbe =        AndroidAccelerometerProbe(context)    @Provides @Singleton    fun provideSensorDutyCyclingController(probe: AccelerometerProbe): SensorDutyCyclingController =        SensorDutyCyclingController(probe)    @Provides @Singleton    fun provideBatteryProbe(@ApplicationContext context: Context): BatteryProbe =        AndroidBatteryProbe(context)    @Provides @Singleton    fun provideBatteryAdaptiveController(probe: BatteryProbe): BatteryAdaptiveController =        BatteryAdaptiveController(probe)    @Provides @Singleton    fun provideLmkEvictionOrchestrator(        evictionTarget: com.roshan.persona.vision.infrastructure.RealVisionEvictionTarget,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): LmkEvictionOrchestrator = LmkEvictionOrchestrator(        evictionTarget,        dispatcher,    )    @Provides @Singleton    fun provideFallbackChainOrchestrator(        chain: com.roshan.persona.vision.infrastructure.RealVisionEngineChain,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): FallbackChainOrchestrator = FallbackChainOrchestrator(        chain,        dispatcher,    )    // ─── Regional Vision Packs ───────────────────────────────────────────    @Provides @Singleton    fun providePackDownloader(        httpClient: okhttp3.OkHttpClient,    ): PackDownloader = OkHttpPackDownloader(httpClient)    @Provides @Singleton    fun providePackVerifier(): PackVerifier = Sha256PackVerifier()    @Provides @Singleton    fun provideRegionalVisionPackLoader(        @ApplicationContext context: Context,        downloader: PackDownloader,        verifier: PackVerifier,    ): RegionalVisionPackLoader = RegionalVisionPackLoader(context, downloader, verifier)    // ─── VisionFacade ────────────────────────────────────────────────────    @Provides @Singleton    fun provideVisionFacade(        modelManager: ModelManager,        ocrEngine: OcrEngine,        documentScannerEngine: DocumentScannerEngine,        objectDetectionEngine: ObjectDetectionEngine,        faceDetectionEngine: FaceDetectionEngine,        barcodeScannerEngine: BarcodeScannerEngine,        upiQrHandler: UpiQrHandler,        episodicMemory: VisualEpisodicMemory,        graphRAGConnector: GraphRAGConnector,        screenUnderstandingEngine: ScreenUnderstandingEngine,        thermalGovernor: ThermalGovernor,        sensorDutyCyclingController: SensorDutyCyclingController,        batteryAdaptiveController: BatteryAdaptiveController,        lmkEvictionOrchestrator: LmkEvictionOrchestrator,        fallbackChainOrchestrator: FallbackChainOrchestrator,        regionalPackLoader: RegionalVisionPackLoader,    ): VisionFacade = VisionFacade(        modelManager, ocrEngine, documentScannerEngine, objectDetectionEngine,        faceDetectionEngine, barcodeScannerEngine, upiQrHandler,        episodicMemory, graphRAGConnecto